#pragma material(Domain = "Surface", ShadingModel = "Unlit")
// A minimal 1.x material: every section once, comments in every place a comment can sit.

// The tint the artist sees.
/// @group Look
/// @sort 32
uniform float4 Tint = float4(1.0, 0.5, 0.25, 1.0);
/// @sort 32
uniform float Strength = 2.0;

export void M_MgMinimal(inout material Base)
{
    float3 Color = float3(0, 0, 0);
    // Scale the tint.
    Color = Tint.rgb * Strength; // trailing note
    Base.EmissiveColor = Color;
}
